import type { AttributeId, RegionId, Skill, StarterProject } from '../types';

export interface EvidenceMilestone { xp: 60 | 240 | 720; title: string; output: string }
export interface SkillGuide { tip: string; milestones: EvidenceMilestone[] }
type EvidencePath = [[string, string], [string, string], [string, string]];
interface ExtraDefinition { skill: Skill; starter: StarterProject; guide: SkillGuide }
const catalogAt = '2026-01-01T00:00:00.000Z';
function guide(tip: string, path: EvidencePath): SkillGuide {
  return { tip, milestones: path.map(([title, output], i) => ({ xp: [60, 240, 720][i] as EvidenceMilestone['xp'], title, output })) };
}
function extra(id: string, name: string, regionId: RegionId, category: string, icon: string, description: string,
  attributes: [AttributeId, AttributeId], title: string, outputCriterion: string, actions: [string, string, string], tip: string, path: EvidencePath): ExtraDefinition {
  return {
    skill: { id, name, regionId, category, icon, description, revision: 0, createdAt: catalogAt, updatedAt: catalogAt,
      affinities: [{ attribute: attributes[0], percent: 70 }, { attribute: attributes[1], percent: 30 }],
      equipped: false, archived: false, custom: false },
    starter: { title, description, outputCriterion, actions }, guide: guide(tip, path),
  };
}

